head.script:
let curID = '';
let oldID = '';

// 생성 중 발생한 JS 오류 건수 (예약어 id 설정 시 오류 발생 여부 확인용)
scwin.gErrCount = 0;
window.addEventListener("error", function () { scwin.gErrCount++; });


// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[aliasDataMap > P > id]<br/>AliasDataMap 모듈의 ID 를 설정합니다.",
    "validation" : [
        "동일 Scope 에서 AliasDataMap 모듈을 구별할 수 있는 유일값을 설정합니다.",
        "속성명이나 메소드명과 같은 예약어를 설정할 경우 오류가 발생할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = function () {
    curID = con_ID.getText();

    // 기존 target(alias) 삭제 후 원본 삭제
    if (oldID !== '' && $p.getComponentById(oldID)) {
        $p.data.remove(oldID);
    }

    if (typeof dma_org !== 'undefined') {
        $p.data.remove("dma_org");
    }

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }

    scwin.gErrCount = 0;

    // alias 원본 dataMap 생성
    $c.gcm.createBasicDataMap('', '', 'dma_org');

    // target 생성 (aliasDataMap : scope 속성에 원본 dataMap ID 지정)
    let strTarget = '<w2:aliasDataMap ' + $c.gcm.getNameSpace() + ' id="' + curID + '" scope="dma_org"></w2:aliasDataMap>';

    try {
        $p.data.create(strTarget);
    } catch (ex) {
        scwin.gErrCount++;
    }

    oldID = curID;

    // input 생성 (설정한 ID 로 alias 의 key1 바인딩)
    $c.gcm.createEmptyInput('ref="data:' + curID + '.key1" style="width:200px;"', '', 'input1');

    scwin.btn_getComponent_onclick();
}



// validation 1, 2 판정 출력 : 설정한 ID / 원본 ID 로 각각 조회한 모듈 구분 + 생성 중 오류 건수
scwin.btn_getComponent_onclick = function (e) {
    let objAlias = $p.getComponentById(curID);
    let objOrg = $p.getComponentById("dma_org");
    let strAlias = objAlias ? objAlias.getOption("pluginName") + " (scope : " + objAlias.getOption("scope") + ")" : "조회 실패";
    let strOrg = objOrg ? objOrg.getOption("pluginName") : "조회 실패";

    wf_body_bottom.getObj("scwin").setReturnValue("ID(" + curID + ") 로 조회 : " + strAlias + " / 원본 ID(dma_org) 로 조회 : " + strOrg + " / 생성 중 오류 : " + scwin.gErrCount + "건");
};
